from __future__ import annotations

import json
import os
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable
from html import escape


@dataclass
class ViewIr:
    version: int
    root: list[dict[str, Any]]


EventPayload = dict[str, Any]
EventHandler = Callable[[EventPayload, "ViewSession"], None]


class ViewSession:
    def __init__(self, path: str | Path, context: dict[str, Any] | None = None) -> None:
        self.path = Path(path)
        self.context = dict(context or {})
        self._handlers: dict[str, EventHandler] = {}

    def on(self, handler: str, callback: EventHandler) -> "ViewSession":
        self._handlers[handler] = callback
        return self

    def render_ir(self) -> ViewIr:
        return render_ir(self.path, self.context)

    def render_html(self) -> str:
        return "".join(_render_node(node) for node in self.render_ir().root)

    def dispatch(self, event: str | EventPayload) -> ViewIr:
        payload = {"handler": event} if isinstance(event, str) else event
        handler = str(payload.get("handler", ""))
        if handler.startswith("bind:"):
            parts = handler.removeprefix("bind:").split(":", 1)
            if len(parts) == 2:
                self.context[parts[0]] = parts[1]
        callback = self._handlers.get(handler)
        if callback is not None:
            callback(payload, self)
        return self.render_ir()


def _crepus_bin() -> str:
    return os.environ.get("CREPUS_BIN", "crepus")


def render_ir(path: str | Path, context: dict[str, Any] | None = None) -> ViewIr:
    args = [_crepus_bin(), "native", "ir", str(path)]
    input_data = None
    if context is not None:
        source = Path(path).read_text()
        payload = {"template": source, "context": context, "baseDir": str(Path(path).parent)}
        args = [_crepus_bin(), "native", "ir", "--stdin-json"]
        input_data = json.dumps(payload)
    proc = subprocess.run(args, input=input_data, text=True, capture_output=True, check=False)
    if proc.returncode != 0:
        raise RuntimeError(proc.stderr.strip())
    data = json.loads(proc.stdout)
    return ViewIr(version=data["version"], root=data["root"])


def render_html(path: str | Path, context: dict[str, Any] | None = None) -> str:
    return "".join(_render_node(node) for node in render_ir(path, context).root)


def _render_node(node: dict[str, Any]) -> str:
    kind = node.get("kind")
    if kind == "text":
        return escape(str(node.get("content", "")))
    if kind == "stack":
        axis = escape(str(node.get("axis", "column")))
        children = "".join(_render_node(child) for child in node.get("children", []))
        return f'<div data-crepus-kind="stack" data-axis="{axis}">{children}</div>'
    if kind == "scroll":
        axis = escape(str(node.get("axis", "column")))
        children = "".join(_render_node(child) for child in node.get("children", []))
        return f'<div data-crepus-kind="scroll" data-axis="{axis}">{children}</div>'
    if kind == "button":
        label = escape(str(node.get("label", "")))
        on_click = escape(str(node.get("onClick", "")))
        attr = f' data-onclick="{on_click}"' if on_click else ""
        return f"<button{attr}>{label}</button>"
    if kind == "image":
        src = escape(str(node.get("src", "")), quote=True)
        alt = escape(str(node.get("alt", "")), quote=True)
        return f'<img src="{src}" alt="{alt}">'
    if kind == "slotRotate":
        phrase = escape(str((node.get("phrases") or [""])[0]))
        return f'<span data-crepus-kind="slotRotate">{phrase}</span>'
    if kind == "input":
        placeholder = escape(str(node.get("placeholder", "")), quote=True)
        bind = escape(str(node.get("bind", "")), quote=True)
        if node.get("multiline"):
            return f'<textarea data-bind="{bind}" placeholder="{placeholder}"></textarea>'
        return f'<input data-bind="{bind}" placeholder="{placeholder}">'
    if kind == "picker":
        bind = escape(str(node.get("bind", "")), quote=True)
        options = "".join(
            f'<option value="{escape(str(opt.get("value", "")), quote=True)}">{escape(str(opt.get("label", "")))}</option>'
            for opt in node.get("options", [])
        )
        return f'<select data-bind="{bind}">{options}</select>'
    return ""

import { spawnSync } from "node:child_process"

export interface ViewIr {
  version: number
  root: Array<Record<string, unknown>>
}

function crepusBin(): string {
  return process.env.CREPUS_BIN ?? "crepus"
}

export async function renderIr(path: string, context: Record<string, unknown> = {}): Promise<ViewIr> {
  const template = await Bun.file(path).text()
  const proc = spawnSync(crepusBin(), ["native", "ir", "--stdin-json"], {
    input: JSON.stringify({ template, context }),
    encoding: "utf8"
  })
  if (proc.status !== 0) {
    throw new Error(proc.stderr)
  }
  return JSON.parse(proc.stdout) as ViewIr
}

export async function renderHtml(path: string, context: Record<string, unknown> = {}): Promise<string> {
  const ir = await renderIr(path, context)
  return ir.root.map(renderNode).join("")
}

export type EventPayload = {
  handler: string
  payload?: unknown
}

export type EventHandler = (event: EventPayload, session: CrepusViewSession) => void | Promise<void>

export class CrepusViewSession {
  readonly path: string
  context: Record<string, unknown>
  private handlers = new Map<string, EventHandler>()

  constructor(path: string, context: Record<string, unknown> = {}) {
    this.path = path
    this.context = { ...context }
  }

  on(handler: string, callback: EventHandler): this {
    this.handlers.set(handler, callback)
    return this
  }

  async renderIr(): Promise<ViewIr> {
    return renderIr(this.path, this.context)
  }

  async renderHtml(): Promise<string> {
    const ir = await this.renderIr()
    return ir.root.map(renderNode).join("")
  }

  async dispatch(event: string | EventPayload): Promise<ViewIr> {
    const parsed = typeof event === "string" ? { handler: event } : event
    if (parsed.handler.startsWith("bind:")) {
      const [, key, ...rest] = parsed.handler.split(":")
      this.context[key] = rest.join(":")
    }
    const callback = this.handlers.get(parsed.handler)
    if (callback) {
      await callback(parsed, this)
    }
    return this.renderIr()
  }
}

function renderNode(node: Record<string, unknown>): string {
  switch (node.kind) {
    case "text":
      return escapeHtml(String(node.content ?? ""))
    case "stack":
    case "scroll":
      return `<div data-crepus-kind="${escapeAttr(String(node.kind))}" data-axis="${escapeAttr(String(node.axis ?? "column"))}">${children(node)}</div>`
    case "button": {
      const label = escapeHtml(String(node.label ?? ""))
      const onClick = node.onClick ? ` data-onclick="${escapeAttr(String(node.onClick))}"` : ""
      return `<button${onClick}>${label}</button>`
    }
    case "image":
      return `<img src="${escapeAttr(String(node.src ?? ""))}" alt="${escapeAttr(String(node.alt ?? ""))}">`
    case "slotRotate":
      return `<span data-crepus-kind="slotRotate">${escapeHtml(String((node.phrases as unknown[] | undefined)?.[0] ?? ""))}</span>`
    case "input":
      return node.multiline
        ? `<textarea data-bind="${escapeAttr(String(node.bind ?? ""))}" placeholder="${escapeAttr(String(node.placeholder ?? ""))}"></textarea>`
        : `<input data-bind="${escapeAttr(String(node.bind ?? ""))}" placeholder="${escapeAttr(String(node.placeholder ?? ""))}">`
    case "picker":
      return `<select data-bind="${escapeAttr(String(node.bind ?? ""))}">${(node.options as Array<Record<string, unknown>> | undefined ?? []).map((opt) => `<option value="${escapeAttr(String(opt.value ?? ""))}">${escapeHtml(String(opt.label ?? ""))}</option>`).join("")}</select>`
    default:
      return ""
  }
}

function children(node: Record<string, unknown>): string {
  return (node.children as Array<Record<string, unknown>> | undefined ?? []).map(renderNode).join("")
}

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
}

function escapeAttr(value: string): string {
  return escapeHtml(value).replaceAll('"', "&quot;")
}

package crepuscularity

import (
	"bytes"
	"encoding/json"
	"fmt"
	"html"
	"os"
	"os/exec"
	"strings"
)

type ViewIr struct {
	Version int              `json:"version"`
	Root    []map[string]any `json:"root"`
}

type Event struct {
	Handler string         `json:"handler"`
	Payload map[string]any `json:"payload,omitempty"`
}

type EventHandler func(Event, *ViewSession) error

type ViewSession struct {
	Path    string
	Context map[string]any
	events  map[string]EventHandler
}

func crepusBin() string {
	if bin := os.Getenv("CREPUS_BIN"); bin != "" {
		return bin
	}
	return "crepus"
}

func RenderIR(path string, context map[string]any) (ViewIr, error) {
	payload, err := json.Marshal(map[string]any{
		"template": mustRead(path),
		"context":  context,
	})
	if err != nil {
		return ViewIr{}, err
	}
	cmd := exec.Command(crepusBin(), "native", "ir", "--stdin-json")
	cmd.Stdin = bytes.NewReader(payload)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return ViewIr{}, fmt.Errorf("%w: %s", err, string(out))
	}
	var ir ViewIr
	if err := json.Unmarshal(out, &ir); err != nil {
		return ViewIr{}, err
	}
	return ir, nil
}

func mustRead(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	return string(data)
}

func RenderHTML(path string, context map[string]any) (string, error) {
	ir, err := RenderIR(path, context)
	if err != nil {
		return "", err
	}
	var out strings.Builder
	for _, node := range ir.Root {
		out.WriteString(renderNode(node))
	}
	return out.String(), nil
}

func NewViewSession(path string, context map[string]any) *ViewSession {
	if context == nil {
		context = map[string]any{}
	}
	return &ViewSession{Path: path, Context: context, events: map[string]EventHandler{}}
}

func (session *ViewSession) On(handler string, callback EventHandler) *ViewSession {
	session.events[handler] = callback
	return session
}

func (session *ViewSession) RenderIR() (ViewIr, error) {
	return RenderIR(session.Path, session.Context)
}

func (session *ViewSession) RenderHTML() (string, error) {
	return RenderHTML(session.Path, session.Context)
}

func (session *ViewSession) Dispatch(event Event) (ViewIr, error) {
	if strings.HasPrefix(event.Handler, "bind:") {
		parts := strings.SplitN(strings.TrimPrefix(event.Handler, "bind:"), ":", 2)
		if len(parts) == 2 {
			session.Context[parts[0]] = parts[1]
		}
	}
	if callback := session.events[event.Handler]; callback != nil {
		if err := callback(event, session); err != nil {
			return ViewIr{}, err
		}
	}
	return session.RenderIR()
}

func renderNode(node map[string]any) string {
	switch node["kind"] {
	case "text":
		return html.EscapeString(fmt.Sprint(node["content"]))
	case "stack", "scroll":
		var out strings.Builder
		out.WriteString(`<div data-crepus-kind="`)
		out.WriteString(html.EscapeString(fmt.Sprint(node["kind"])))
		out.WriteString(`" data-axis="`)
		out.WriteString(html.EscapeString(fmt.Sprint(node["axis"])))
		out.WriteString(`">`)
		for _, child := range nodeList(node["children"]) {
			out.WriteString(renderNode(child))
		}
		out.WriteString("</div>")
		return out.String()
	case "button":
		label := html.EscapeString(fmt.Sprint(node["label"]))
		if node["onClick"] != nil {
			return `<button data-onclick="` + html.EscapeString(fmt.Sprint(node["onClick"])) + `">` + label + `</button>`
		}
		return "<button>" + label + "</button>"
	case "image":
		return `<img src="` + html.EscapeString(fmt.Sprint(node["src"])) + `" alt="` + html.EscapeString(fmt.Sprint(node["alt"])) + `">`
	case "slotRotate":
		phrases := valueList(node["phrases"])
		if len(phrases) == 0 {
			return `<span data-crepus-kind="slotRotate"></span>`
		}
		return `<span data-crepus-kind="slotRotate">` + html.EscapeString(fmt.Sprint(phrases[0])) + `</span>`
	case "input":
		bind := html.EscapeString(fmt.Sprint(node["bind"]))
		placeholder := html.EscapeString(fmt.Sprint(node["placeholder"]))
		if node["multiline"] == true {
			return `<textarea data-bind="` + bind + `" placeholder="` + placeholder + `"></textarea>`
		}
		return `<input data-bind="` + bind + `" placeholder="` + placeholder + `">`
	case "picker":
		var out strings.Builder
		out.WriteString(`<select data-bind="`)
		out.WriteString(html.EscapeString(fmt.Sprint(node["bind"])))
		out.WriteString(`">`)
		for _, option := range nodeList(node["options"]) {
			out.WriteString(`<option value="`)
			out.WriteString(html.EscapeString(fmt.Sprint(option["value"])))
			out.WriteString(`">`)
			out.WriteString(html.EscapeString(fmt.Sprint(option["label"])))
			out.WriteString(`</option>`)
		}
		out.WriteString(`</select>`)
		return out.String()
	default:
		return ""
	}
}

func nodeList(value any) []map[string]any {
	raw, ok := value.([]any)
	if !ok {
		return nil
	}
	out := make([]map[string]any, 0, len(raw))
	for _, item := range raw {
		if node, ok := item.(map[string]any); ok {
			out = append(out, node)
		}
	}
	return out
}

func valueList(value any) []any {
	raw, _ := value.([]any)
	return raw
}

