//! crepuscularity-webext — Browser extension capabilities with auto-detection
//!
//! This crate provides opt-in capability management for browser extensions,
//! inspired by Equilibrium's `.eqp` capability system. Extensions declare
//! capabilities in a manifest, and the CLI watches files to auto-detect
//! and suggest missing capabilities.
//!
//! # Example Manifest (manifest.crex)
//!
//! ```toml
//! [extension]
//! name = "my-extension"
//! version = "1.0.0"
//!
//! [capabilities]
//! content-script = true
//! storage = true
//! messaging = true
//! host-permissions = ["https://example.com/*"]
//! ```

pub mod extension_assets;

mod api;
mod capabilities;
mod manifest;
mod scanner;
#[cfg(any(feature = "wasm", test))]
mod wasm_schema;
mod watcher;
pub mod widgets;

#[cfg(feature = "wasm")]
pub mod wasm;

pub use api::{
    BrowserProgram, BrowserSource, BrowserStatement, JsExpr, MessagePayload, StorageArea,
};
pub use capabilities::{Capability, CapabilitySet};
pub use manifest::{
    ActionSpec, BackgroundSpec, BrowserTarget, CapabilitiesSection, ContentScriptEntry,
    ContentScriptSpec, ExtensionInfo, ExtensionManifest, ExtensionManifestCommand, ManifestError,
    ManifestOptions, ManifestV3, OptionsUiSpec, PluginEntry, WebAccessibleResources,
    WebAccessibleResourcesOptions,
};
pub use scanner::{scan_crepus_for_capabilities, CapabilityUsage};
pub use watcher::{check_project_capabilities, CapabilityWatcher, WatchEvent};
pub use widgets::{build_frame_doc, json_to_template};

/// `crepus render <file.crepus>` — render a template to HTML on stdout.
///
/// OPTIONS:
///   --ctx <file>    load context variables from a TOML or JSON file
///   --var key=value set a single context variable (repeatable)
///   --component Name render a named component from a multi-component file
use std::path::{Path, PathBuf};

use crepuscularity_core::context::{TemplateContext, TemplateValue};
use crepuscularity_web::{render_component_file_to_html, render_template_to_html};
use serde_json::Value;

use crate::ui;

pub fn run(args: &[String]) {
    let mut path: Option<PathBuf> = None;
    let mut ctx_file: Option<PathBuf> = None;
    let mut vars: Vec<(String, String)> = Vec::new();
    let mut component: Option<String> = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--ctx" => {
                i += 1;
                ctx_file = args.get(i).map(PathBuf::from);
            }
            "--var" => {
                i += 1;
                if let Some(kv) = args.get(i) {
                    if let Some(eq) = kv.find('=') {
                        vars.push((kv[..eq].to_string(), kv[eq + 1..].to_string()));
                    } else {
                        ui::error(&format!("--var expects key=value, got: {kv}"));
                    }
                }
            }
            "--component" => {
                i += 1;
                component = args.get(i).cloned();
            }
            other => {
                if other.starts_with('-') {
                    ui::error(&format!("unknown option: {other}"));
                } else if path.is_none() {
                    path = Some(PathBuf::from(other));
                } else {
                    ui::error(&format!("unexpected argument: {other}"));
                }
            }
        }
        i += 1;
    }

    let path = path.unwrap_or_else(|| {
        eprintln!("Usage: crepus render <file.crepus> [--ctx FILE] [--var k=v] [--component Name]");
        std::process::exit(1);
    });

    if !path.exists() {
        ui::error(&format!("file not found: {}", path.display()));
    }

    let mut ctx = TemplateContext::new();
    ctx.base_dir = path.parent().map(|p| p.to_path_buf());

    if let Some(ctx_path) = ctx_file {
        load_ctx_file(&ctx_path, &mut ctx);
    } else if let Some(dir) = path.parent() {
        let auto = dir.join("context.toml");
        if auto.exists() {
            load_ctx_file(&auto, &mut ctx);
        }
    }

    for (k, v) in vars {
        ctx.set(k, v);
    }

    let content = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        ui::error(&format!("failed to read {}: {e}", path.display()));
    });

    let html = match component {
        Some(ref name) => render_component_file_to_html(&content, name, &ctx),
        None => render_template_to_html(&content, &ctx),
    };

    match html {
        Ok(out) => print!("{out}"),
        Err(e) => ui::error(&format!("Render error: {e}")),
    }
}

fn load_toml_ctx(path: &Path, ctx: &mut TemplateContext) {
    let Ok(content) = std::fs::read_to_string(path) else {
        ui::warning(&format!("could not read context file: {}", path.display()));
        return;
    };
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with('[') {
            continue;
        }
        if let Some(eq) = line.find('=') {
            let key = line[..eq].trim();
            let val = line[eq + 1..].trim();
            let value = if val == "true" {
                TemplateValue::Bool(true)
            } else if val == "false" {
                TemplateValue::Bool(false)
            } else if let Ok(n) = val.parse::<i64>() {
                TemplateValue::Int(n)
            } else if let Ok(f) = val.parse::<f64>() {
                TemplateValue::Float(f)
            } else {
                TemplateValue::Str(val.trim_matches('"').trim_matches('\'').to_string())
            };
            ctx.set(key, value);
        }
    }
}

fn load_ctx_file(path: &Path, ctx: &mut TemplateContext) {
    let Ok(content) = std::fs::read_to_string(path) else {
        ui::warning(&format!("could not read context file: {}", path.display()));
        return;
    };
    // Try JSON first, fall back to TOML
    if let Ok(value) = serde_json::from_str::<Value>(&content) {
        load_json_ctx_value(&value, ctx);
    } else {
        load_toml_ctx(path, ctx);
    }
}

fn load_json_ctx_value(value: &Value, ctx: &mut TemplateContext) {
    let Some(obj) = value.as_object() else {
        return;
    };
    for (key, val) in obj {
        if let Ok(v) = json_to_template_value(val) {
            ctx.set(key.clone(), v);
        }
    }
}

fn json_to_template_value(value: &Value) -> Result<TemplateValue, ()> {
    match value {
        Value::Null => Ok(TemplateValue::Null),
        Value::Bool(v) => Ok(TemplateValue::Bool(*v)),
        Value::Number(v) => {
            if let Some(n) = v.as_i64() {
                Ok(TemplateValue::Int(n))
            } else if let Some(n) = v.as_f64() {
                Ok(TemplateValue::Float(n))
            } else {
                Err(())
            }
        }
        Value::String(v) => Ok(TemplateValue::Str(v.clone())),
        Value::Array(values) => {
            // Check if array items are scalars (strings/numbers/bools) or objects
            let mut items = Vec::new();
            for item in values {
                match item {
                    Value::Object(obj) => {
                        // Each object becomes a child context
                        let mut child = TemplateContext::new();
                        for (key, value) in obj {
                            if let Ok(v) = json_to_template_scalar(value) {
                                child.set(key.clone(), v);
                            }
                        }
                        items.push(child);
                    }
                    Value::String(_) | Value::Number(_) | Value::Bool(_) | Value::Null => {
                        // Scalar values become item contexts with "value" key
                        let mut child = TemplateContext::new();
                        if let Ok(v) = json_to_template_scalar(item) {
                            child.set("value", v);
                        }
                        items.push(child);
                    }
                    _ => return Err(()),
                }
            }
            Ok(TemplateValue::List(items))
        }
        Value::Object(_) => Err(()),
    }
}

fn json_to_template_scalar(value: &Value) -> Result<TemplateValue, ()> {
    match value {
        Value::Array(_) | Value::Object(_) => Err(()),
        _ => json_to_template_value(value),
    }
}

//! Safe resolution of `include` paths relative to a template `base_dir`.

use std::path::{Path, PathBuf};

use crate::error::CrepusError;

/// Resolve an `include` path, rejecting escapes outside `base_dir`.
///
/// On native targets, existing paths are canonicalized and must stay under the
/// canonical base directory when one is set. Missing paths return a lexical join
/// under the canonical base (virtual bundles and not-yet-written files).
/// On `wasm32`, only syntactic checks run.
pub fn resolve_include_path(base_dir: Option<&Path>, path: &str) -> Result<PathBuf, CrepusError> {
    let requested = Path::new(path);
    if requested.has_root()
        || requested.components().any(|c| {
            matches!(
                c,
                std::path::Component::ParentDir | std::path::Component::Prefix(_)
            )
        })
    {
        return Err(CrepusError::include_path(format!(
            "include path outside base dir: {path}"
        )));
    }

    let candidate = if let Some(base) = base_dir {
        base.join(requested)
    } else {
        requested.to_path_buf()
    };

    #[cfg(not(target_arch = "wasm32"))]
    {
        if let Some(base) = base_dir {
            match std::fs::canonicalize(base) {
                Ok(base) => {
                    let joined = base.join(requested);
                    if !joined.starts_with(&base) {
                        return Err(CrepusError::include_path(format!(
                            "include path outside base dir: {path}"
                        )));
                    }
                    if joined.exists() {
                        let resolved = std::fs::canonicalize(&joined).map_err(|e| {
                            CrepusError::include_path(format!(
                                "failed to resolve include path {path:?}: {e}"
                            ))
                        })?;
                        if !resolved.starts_with(&base) {
                            return Err(CrepusError::include_path(format!(
                                "include path outside base dir: {path}"
                            )));
                        }
                        Ok(resolved)
                    } else {
                        Ok(joined)
                    }
                }
                Err(_) => {
                    // Synthetic bases (virtual bundles, tests) have no on-disk directory.
                    let joined = base.join(requested);
                    if !joined.starts_with(base) {
                        return Err(CrepusError::include_path(format!(
                            "include path outside base dir: {path}"
                        )));
                    }
                    Ok(joined)
                }
            }
        } else if candidate.exists() {
            std::fs::canonicalize(&candidate).map_err(|e| {
                CrepusError::include_path(format!("failed to resolve include path {path:?}: {e}"))
            })
        } else {
            Ok(candidate)
        }
    }

    #[cfg(target_arch = "wasm32")]
    {
        Ok(candidate)
    }
}

#[cfg(test)]
mod tests {
    use super::resolve_include_path;

    #[test]
    fn include_path_rejects_parent_dir() {
        let err = resolve_include_path(None, "../secret.crepus").unwrap_err();
        assert!(err.to_string().contains("include path outside base dir"));
    }

    #[test]
    fn include_path_rejects_absolute_path() {
        let path = std::env::temp_dir().join("secret.crepus");
        let err = resolve_include_path(None, path.to_str().unwrap()).unwrap_err();
        assert!(err.to_string().contains("include path outside base dir"));
    }

    #[test]
    fn include_path_resolves_with_base_dir() {
        let dir = tempfile::tempdir().expect("tempdir");
        let base = dir.path();
        std::fs::write(base.join("foo.crepus"), "div").expect("write fixture");
        let res = resolve_include_path(Some(base), "foo.crepus").unwrap();
        let expected = std::fs::canonicalize(base.join("foo.crepus")).expect("canonicalize");
        assert_eq!(res, expected);
    }

    #[test]
    fn include_path_resolves_without_base_dir() {
        let res = resolve_include_path(None, "foo.crepus").unwrap();
        assert_eq!(res, std::path::PathBuf::from("foo.crepus"));
    }

    #[test]
    fn include_path_resolves_nested() {
        let res = resolve_include_path(None, "foo/bar.crepus").unwrap();
        assert_eq!(res, std::path::PathBuf::from("foo/bar.crepus"));
    }

    #[test]
    fn include_path_rejects_nested_parent_dir() {
        let err = resolve_include_path(None, "foo/../bar.crepus").unwrap_err();
        assert!(err.to_string().contains("include path outside base dir"));
    }

    #[cfg(unix)]
