from __future__ import annotations

import json
import os
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable
from html import escape


@dataclass
class ViewIr:
    version: int
    root: list[dict[str, Any]]


EventPayload = dict[str, Any]
EventHandler = Callable[[EventPayload, "ViewSession"], None]


class ViewSession:
    def __init__(self, path: str | Path, context: dict[str, Any] | None = None) -> None:
        self.path = Path(path)
        self.context = dict(context or {})
        self._handlers: dict[str, EventHandler] = {}

    def on(self, handler: str, callback: EventHandler) -> "ViewSession":
        self._handlers[handler] = callback
        return self

    def render_ir(self) -> ViewIr:
        return render_ir(self.path, self.context)

    def render_html(self) -> str:
        return "".join(_render_node(node) for node in self.render_ir().root)

    def dispatch(self, event: str | EventPayload) -> ViewIr:
        payload = {"handler": event} if isinstance(event, str) else event
        handler = str(payload.get("handler", ""))
        if handler.startswith("bind:"):
            parts = handler.removeprefix("bind:").split(":", 1)
            if len(parts) == 2:
                self.context[parts[0]] = parts[1]
        callback = self._handlers.get(handler)
        if callback is not None:
            callback(payload, self)
        return self.render_ir()


def _crepus_bin() -> str:
    return os.environ.get("CREPUS_BIN", "crepus")


def render_ir(path: str | Path, context: dict[str, Any] | None = None) -> ViewIr:
    args = [_crepus_bin(), "native", "ir", str(path)]
    input_data = None
    if context is not None:
        source = Path(path).read_text()
        payload = {"template": source, "context": context, "baseDir": str(Path(path).parent)}
        args = [_crepus_bin(), "native", "ir", "--stdin-json"]
        input_data = json.dumps(payload)
    proc = subprocess.run(args, input=input_data, text=True, capture_output=True, check=False)
    if proc.returncode != 0:
        raise RuntimeError(proc.stderr.strip())
    data = json.loads(proc.stdout)
    return ViewIr(version=data["version"], root=data["root"])


def render_html(path: str | Path, context: dict[str, Any] | None = None) -> str:
    return "".join(_render_node(node) for node in render_ir(path, context).root)


def _render_node(node: dict[str, Any]) -> str:
    kind = node.get("kind")
    if kind == "text":
        return escape(str(node.get("content", "")))
    if kind == "stack":
        axis = escape(str(node.get("axis", "column")))
        children = "".join(_render_node(child) for child in node.get("children", []))
        return f'<div data-crepus-kind="stack" data-axis="{axis}">{children}</div>'
    if kind == "scroll":
        axis = escape(str(node.get("axis", "column")))
        children = "".join(_render_node(child) for child in node.get("children", []))
        return f'<div data-crepus-kind="scroll" data-axis="{axis}">{children}</div>'
    if kind == "button":
        label = escape(str(node.get("label", "")))
        on_click = escape(str(node.get("onClick", "")))
        attr = f' data-onclick="{on_click}"' if on_click else ""
        return f"<button{attr}>{label}</button>"
    if kind == "image":
        src = escape(str(node.get("src", "")), quote=True)
        alt = escape(str(node.get("alt", "")), quote=True)
        return f'<img src="{src}" alt="{alt}">'
    if kind == "slotRotate":
        phrase = escape(str((node.get("phrases") or [""])[0]))
        return f'<span data-crepus-kind="slotRotate">{phrase}</span>'
    if kind == "input":
        placeholder = escape(str(node.get("placeholder", "")), quote=True)
        bind = escape(str(node.get("bind", "")), quote=True)
        if node.get("multiline"):
            return f'<textarea data-bind="{bind}" placeholder="{placeholder}"></textarea>'
        return f'<input data-bind="{bind}" placeholder="{placeholder}">'
    if kind == "picker":
        bind = escape(str(node.get("bind", "")), quote=True)
        options = "".join(
            f'<option value="{escape(str(opt.get("value", "")), quote=True)}">{escape(str(opt.get("label", "")))}</option>'
            for opt in node.get("options", [])
        )
        return f'<select data-bind="{bind}">{options}</select>'
    return ""

package crepuscularity

import (
	"bytes"
	"encoding/json"
	"fmt"
	"html"
	"os"
	"os/exec"
	"strings"
)

type ViewIr struct {
	Version int              `json:"version"`
	Root    []map[string]any `json:"root"`
}

type Event struct {
	Handler string         `json:"handler"`
	Payload map[string]any `json:"payload,omitempty"`
}

type EventHandler func(Event, *ViewSession) error

type ViewSession struct {
	Path    string
	Context map[string]any
	events  map[string]EventHandler
}

func crepusBin() string {
	if bin := os.Getenv("CREPUS_BIN"); bin != "" {
		return bin
	}
	return "crepus"
}

func RenderIR(path string, context map[string]any) (ViewIr, error) {
	payload, err := json.Marshal(map[string]any{
		"template": mustRead(path),
		"context":  context,
	})
	if err != nil {
		return ViewIr{}, err
	}
	cmd := exec.Command(crepusBin(), "native", "ir", "--stdin-json")
	cmd.Stdin = bytes.NewReader(payload)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return ViewIr{}, fmt.Errorf("%w: %s", err, string(out))
	}
	var ir ViewIr
	if err := json.Unmarshal(out, &ir); err != nil {
		return ViewIr{}, err
	}
	return ir, nil
}

func mustRead(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	return string(data)
}

func RenderHTML(path string, context map[string]any) (string, error) {
	ir, err := RenderIR(path, context)
	if err != nil {
		return "", err
	}
	var out strings.Builder
	for _, node := range ir.Root {
		out.WriteString(renderNode(node))
	}
	return out.String(), nil
}

func NewViewSession(path string, context map[string]any) *ViewSession {
	if context == nil {
		context = map[string]any{}
	}
	return &ViewSession{Path: path, Context: context, events: map[string]EventHandler{}}
}

func (session *ViewSession) On(handler string, callback EventHandler) *ViewSession {
	session.events[handler] = callback
	return session
}

func (session *ViewSession) RenderIR() (ViewIr, error) {
	return RenderIR(session.Path, session.Context)
}

func (session *ViewSession) RenderHTML() (string, error) {
	return RenderHTML(session.Path, session.Context)
}

func (session *ViewSession) Dispatch(event Event) (ViewIr, error) {
	if strings.HasPrefix(event.Handler, "bind:") {
		parts := strings.SplitN(strings.TrimPrefix(event.Handler, "bind:"), ":", 2)
		if len(parts) == 2 {
			session.Context[parts[0]] = parts[1]
		}
	}
	if callback := session.events[event.Handler]; callback != nil {
		if err := callback(event, session); err != nil {
			return ViewIr{}, err
		}
	}
	return session.RenderIR()
}

func renderNode(node map[string]any) string {
	switch node["kind"] {
	case "text":
		return html.EscapeString(fmt.Sprint(node["content"]))
	case "stack", "scroll":
		var out strings.Builder
		out.WriteString(`<div data-crepus-kind="`)
		out.WriteString(html.EscapeString(fmt.Sprint(node["kind"])))
		out.WriteString(`" data-axis="`)
		out.WriteString(html.EscapeString(fmt.Sprint(node["axis"])))
		out.WriteString(`">`)
		for _, child := range nodeList(node["children"]) {
			out.WriteString(renderNode(child))
		}
		out.WriteString("</div>")
		return out.String()
	case "button":
		label := html.EscapeString(fmt.Sprint(node["label"]))
		if node["onClick"] != nil {
			return `<button data-onclick="` + html.EscapeString(fmt.Sprint(node["onClick"])) + `">` + label + `</button>`
		}
		return "<button>" + label + "</button>"
	case "image":
		return `<img src="` + html.EscapeString(fmt.Sprint(node["src"])) + `" alt="` + html.EscapeString(fmt.Sprint(node["alt"])) + `">`
	case "slotRotate":
		phrases := valueList(node["phrases"])
		if len(phrases) == 0 {
			return `<span data-crepus-kind="slotRotate"></span>`
		}
		return `<span data-crepus-kind="slotRotate">` + html.EscapeString(fmt.Sprint(phrases[0])) + `</span>`
	case "input":
		bind := html.EscapeString(fmt.Sprint(node["bind"]))
		placeholder := html.EscapeString(fmt.Sprint(node["placeholder"]))
		if node["multiline"] == true {
			return `<textarea data-bind="` + bind + `" placeholder="` + placeholder + `"></textarea>`
		}
		return `<input data-bind="` + bind + `" placeholder="` + placeholder + `">`
	case "picker":
		var out strings.Builder
		out.WriteString(`<select data-bind="`)
		out.WriteString(html.EscapeString(fmt.Sprint(node["bind"])))
		out.WriteString(`">`)
		for _, option := range nodeList(node["options"]) {
			out.WriteString(`<option value="`)
			out.WriteString(html.EscapeString(fmt.Sprint(option["value"])))
			out.WriteString(`">`)
			out.WriteString(html.EscapeString(fmt.Sprint(option["label"])))
			out.WriteString(`</option>`)
		}
		out.WriteString(`</select>`)
		return out.String()
	default:
		return ""
	}
}

func nodeList(value any) []map[string]any {
	raw, ok := value.([]any)
	if !ok {
		return nil
	}
	out := make([]map[string]any, 0, len(raw))
	for _, item := range raw {
		if node, ok := item.(map[string]any); ok {
			out = append(out, node)
		}
	}
	return out
}

func valueList(value any) []any {
	raw, _ := value.([]any)
	return raw
}

import { spawnSync } from "node:child_process"

export interface ViewIr {
  version: number
  root: Array<Record<string, unknown>>
}

function crepusBin(): string {
  return process.env.CREPUS_BIN ?? "crepus"
}

export async function renderIr(path: string, context: Record<string, unknown> = {}): Promise<ViewIr> {
  const template = await Bun.file(path).text()
  const proc = spawnSync(crepusBin(), ["native", "ir", "--stdin-json"], {
    input: JSON.stringify({ template, context }),
    encoding: "utf8"
  })
  if (proc.status !== 0) {
    throw new Error(proc.stderr)
  }
  return JSON.parse(proc.stdout) as ViewIr
}

export async function renderHtml(path: string, context: Record<string, unknown> = {}): Promise<string> {
  const ir = await renderIr(path, context)
  return ir.root.map(renderNode).join("")
}

export type EventPayload = {
  handler: string
  payload?: unknown
}

export type EventHandler = (event: EventPayload, session: CrepusViewSession) => void | Promise<void>

export class CrepusViewSession {
  readonly path: string
  context: Record<string, unknown>
  private handlers = new Map<string, EventHandler>()

  constructor(path: string, context: Record<string, unknown> = {}) {
    this.path = path
    this.context = { ...context }
  }

  on(handler: string, callback: EventHandler): this {
    this.handlers.set(handler, callback)
    return this
  }

  async renderIr(): Promise<ViewIr> {
    return renderIr(this.path, this.context)
  }

  async renderHtml(): Promise<string> {
    const ir = await this.renderIr()
    return ir.root.map(renderNode).join("")
  }

  async dispatch(event: string | EventPayload): Promise<ViewIr> {
    const parsed = typeof event === "string" ? { handler: event } : event
    if (parsed.handler.startsWith("bind:")) {
      const [, key, ...rest] = parsed.handler.split(":")
      this.context[key] = rest.join(":")
    }
    const callback = this.handlers.get(parsed.handler)
    if (callback) {
      await callback(parsed, this)
    }
    return this.renderIr()
  }
}

function renderNode(node: Record<string, unknown>): string {
  switch (node.kind) {
    case "text":
      return escapeHtml(String(node.content ?? ""))
    case "stack":
    case "scroll":
      return `<div data-crepus-kind="${escapeAttr(String(node.kind))}" data-axis="${escapeAttr(String(node.axis ?? "column"))}">${children(node)}</div>`
    case "button": {
      const label = escapeHtml(String(node.label ?? ""))
      const onClick = node.onClick ? ` data-onclick="${escapeAttr(String(node.onClick))}"` : ""
      return `<button${onClick}>${label}</button>`
    }
    case "image":
      return `<img src="${escapeAttr(String(node.src ?? ""))}" alt="${escapeAttr(String(node.alt ?? ""))}">`
    case "slotRotate":
      return `<span data-crepus-kind="slotRotate">${escapeHtml(String((node.phrases as unknown[] | undefined)?.[0] ?? ""))}</span>`
    case "input":
      return node.multiline
        ? `<textarea data-bind="${escapeAttr(String(node.bind ?? ""))}" placeholder="${escapeAttr(String(node.placeholder ?? ""))}"></textarea>`
        : `<input data-bind="${escapeAttr(String(node.bind ?? ""))}" placeholder="${escapeAttr(String(node.placeholder ?? ""))}">`
    case "picker":
      return `<select data-bind="${escapeAttr(String(node.bind ?? ""))}">${(node.options as Array<Record<string, unknown>> | undefined ?? []).map((opt) => `<option value="${escapeAttr(String(opt.value ?? ""))}">${escapeHtml(String(opt.label ?? ""))}</option>`).join("")}</select>`
    default:
      return ""
  }
}

function children(node: Record<string, unknown>): string {
  return (node.children as Array<Record<string, unknown>> | undefined ?? []).map(renderNode).join("")
}

function escapeHtml(value: string): string {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
}

function escapeAttr(value: string): string {
  return escapeHtml(value).replaceAll('"', "&quot;")
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int crepus_render_ir(const char *path, char *buf, size_t cap) {
    const char *bin = getenv("CREPUS_BIN");
    if (bin == NULL) {
        bin = "crepus";
    }
    char cmd[4096];
    snprintf(cmd, sizeof(cmd), "\"%s\" native ir \"%s\"", bin, path);
    FILE *pipe = popen(cmd, "r");
    if (pipe == NULL) {
        return 1;
    }
    size_t n = fread(buf, 1, cap - 1, pipe);
    buf[n] = '\0';
    return pclose(pipe) == 0 ? 0 : 1;
}

static int crepus_render_html(const char *path, char *buf, size_t cap) {
    char ir[8192];
    if (crepus_render_ir(path, ir, sizeof(ir)) != 0) {
        return 1;
    }
    const char *needle = "\"content\":\"";
    char *start = strstr(ir, needle);
    if (start == NULL) {
        return snprintf(buf, cap, "<div data-crepus-kind=\"stack\" data-axis=\"column\"></div>") < (int)cap ? 0 : 1;
    }
    start += strlen(needle);
    char *end = strchr(start, '"');
    if (end == NULL) {
        end = start;
    }
    return snprintf(buf, cap, "<div data-crepus-kind=\"stack\" data-axis=\"column\">%.*s</div>", (int)(end - start), start) < (int)cap ? 0 : 1;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        return 2;
    }
    char buf[8192];
    if (crepus_render_ir(argv[1], buf, sizeof(buf)) != 0) {
        return 1;
    }
    char html[8192];
    if (crepus_render_html(argv[1], html, sizeof(html)) != 0 || strstr(html, "data-crepus-kind=\"stack\"") == NULL) {
        return 1;
    }
    return strstr(buf, "\"version\":4") || strstr(buf, "\"version\": 4") ? 0 : 1;
}

#include <array>
#include <cstdio>
#include <cstdlib>
#include <stdexcept>
#include <string>

struct ViewIr {
    int version;
    std::string json;
};

ViewIr render_ir(const std::string& path) {
    const char* env = std::getenv("CREPUS_BIN");
    std::string bin = env == nullptr ? "crepus" : env;
    std::string cmd = "\"" + bin + "\" native ir \"" + path + "\"";
    FILE* pipe = popen(cmd.c_str(), "r");
    if (pipe == nullptr) {
        throw std::runtime_error("crepus native ir failed");
    }
    std::array<char, 4096> buffer{};
    std::string json;
    while (fgets(buffer.data(), static_cast<int>(buffer.size()), pipe) != nullptr) {
        json += buffer.data();
    }
    if (pclose(pipe) != 0) {
        throw std::runtime_error("crepus native ir failed");
    }
    int version = json.find("\"version\":4") != std::string::npos || json.find("\"version\": 4") != std::string::npos ? 4 : -1;
    return {version, json};
}

std::string render_html(const std::string& path) {
    const auto ir = render_ir(path);
    const std::string marker = "\"content\":\"";
    const auto start = ir.json.find(marker);
    if (start == std::string::npos) {
        return "<div data-crepus-kind=\"stack\" data-axis=\"column\"></div>";
    }
    const auto content_start = start + marker.size();
    const auto end = ir.json.find('"', content_start);
    const auto content = ir.json.substr(content_start, end - content_start);
    return "<div data-crepus-kind=\"stack\" data-axis=\"column\">" + content + "</div>";
}

int main(int argc, char** argv) {
    if (argc != 2) {
        return 2;
    }
    return render_ir(argv[1]).version == 4 && render_html(argv[1]).find("data-crepus-kind=\"stack\"") != std::string::npos ? 0 : 1;
}

using System.Diagnostics;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Crepuscularity.Plugin;

public sealed record ViewIr(
    [property: JsonPropertyName("version")] int Version,
    [property: JsonPropertyName("root")] JsonElement Root
);

public sealed record EventPayload(string Handler, object? Payload = null);

public sealed class ViewSession
{
    private readonly Dictionary<string, Func<EventPayload, ViewSession, Task>> _handlers = new();

    public ViewSession(string path, IDictionary<string, object?>? context = null)
    {
        Path = path;
        Context = context is null ? new Dictionary<string, object?>() : new Dictionary<string, object?>(context);
    }

    public string Path { get; }

    public Dictionary<string, object?> Context { get; }

    public ViewSession On(string handler, Func<EventPayload, ViewSession, Task> callback)
    {
        _handlers[handler] = callback;
        return this;
    }

    public ViewSession On(string handler, Action<EventPayload, ViewSession> callback)
    {
        _handlers[handler] = (evt, session) =>
        {
            callback(evt, session);
            return Task.CompletedTask;
        };
        return this;
    }

    public Task<ViewIr> RenderIrAsync()
    {
        return Crepuscularity.RenderIrAsync(Path, Context);
    }

    public Task<string> RenderHtmlAsync()
    {
        return Crepuscularity.RenderHtmlAsync(Path, Context);
    }

    public Task<ViewIr> DispatchAsync(string handler)
    {
        return DispatchAsync(new EventPayload(handler));
    }

    public async Task<ViewIr> DispatchAsync(EventPayload evt)
    {
        ApplyBind(evt.Handler);
        if (_handlers.TryGetValue(evt.Handler, out var callback))
        {
            await callback(evt, this);
        }
        return await RenderIrAsync();
    }

    private void ApplyBind(string handler)
    {
        if (!handler.StartsWith("bind:", StringComparison.Ordinal))
        {
            return;
        }
        var rest = handler["bind:".Length..];
        var colon = rest.IndexOf(':');
        if (colon <= 0)
        {
            return;
        }
        Context[rest[..colon]] = rest[(colon + 1)..];
    }
}

public static class Crepuscularity
{
    public static async Task<ViewIr> RenderIrAsync(string path, object? context = null)
    {
        var template = await File.ReadAllTextAsync(path);
        var payload = JsonSerializer.Serialize(new { template, context = context ?? new { } });
        var bin = Environment.GetEnvironmentVariable("CREPUS_BIN") ?? "crepus";
        using var proc = new Process();
        proc.StartInfo = new ProcessStartInfo(bin, "native ir --stdin-json")
        {
            RedirectStandardInput = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };
        proc.Start();
        await proc.StandardInput.WriteAsync(payload);
        proc.StandardInput.Close();
        var stdout = await proc.StandardOutput.ReadToEndAsync();
        var stderr = await proc.StandardError.ReadToEndAsync();
        await proc.WaitForExitAsync();
        if (proc.ExitCode != 0)
        {
            throw new InvalidOperationException(stderr);
        }
        return JsonSerializer.Deserialize<ViewIr>(stdout) ?? throw new InvalidOperationException("empty IR");
    }

    public static async Task<string> RenderHtmlAsync(string path, object? context = null)
    {
        var ir = await RenderIrAsync(path, context);
        return string.Concat(ir.Root.EnumerateArray().Select(RenderNode));
    }

    private static string RenderNode(JsonElement node)
    {
        var kind = node.TryGetProperty("kind", out var kindElement) ? kindElement.GetString() : "";
        return kind switch
        {
            "text" => System.Net.WebUtility.HtmlEncode(node.GetProperty("content").GetString() ?? ""),
            "stack" or "scroll" => $"<div data-crepus-kind=\"{System.Net.WebUtility.HtmlEncode(kind)}\" data-axis=\"{System.Net.WebUtility.HtmlEncode(node.GetProperty("axis").GetString() ?? "column")}\">{string.Concat(node.GetProperty("children").EnumerateArray().Select(RenderNode))}</div>",
            "button" => RenderButton(node),
            "image" => $"<img src=\"{System.Net.WebUtility.HtmlEncode(node.GetProperty("src").GetString() ?? "")}\" alt=\"{System.Net.WebUtility.HtmlEncode(node.GetProperty("alt").GetString() ?? "")}\">",
            "slotRotate" => $"<span data-crepus-kind=\"slotRotate\">{System.Net.WebUtility.HtmlEncode(FirstPhrase(node))}</span>",
            "input" => RenderInput(node),
            "picker" => RenderPicker(node),
            _ => ""
        };
    }

    private static string RenderButton(JsonElement node)
    {
        var label = System.Net.WebUtility.HtmlEncode(node.GetProperty("label").GetString() ?? "");
        if (!node.TryGetProperty("onClick", out var onClick))
        {
            return $"<button>{label}</button>";
        }
        return $"<button data-onclick=\"{System.Net.WebUtility.HtmlEncode(onClick.GetString() ?? "")}\">{label}</button>";
    }

    private static string RenderInput(JsonElement node)
    {
        var bind = System.Net.WebUtility.HtmlEncode(node.GetProperty("bind").GetString() ?? "");
        var placeholder = System.Net.WebUtility.HtmlEncode(node.GetProperty("placeholder").GetString() ?? "");
        if (node.TryGetProperty("multiline", out var multiline) && multiline.ValueKind == JsonValueKind.True)
        {
            return $"<textarea data-bind=\"{bind}\" placeholder=\"{placeholder}\"></textarea>";
        }
        return $"<input data-bind=\"{bind}\" placeholder=\"{placeholder}\">";
    }

    private static string RenderPicker(JsonElement node)
    {
        var bind = System.Net.WebUtility.HtmlEncode(node.GetProperty("bind").GetString() ?? "");
        var options = node.GetProperty("options").EnumerateArray().Select(option =>
            $"<option value=\"{System.Net.WebUtility.HtmlEncode(option.GetProperty("value").GetString() ?? "")}\">{System.Net.WebUtility.HtmlEncode(option.GetProperty("label").GetString() ?? "")}</option>"
        );
        return $"<select data-bind=\"{bind}\">{string.Concat(options)}</select>";
    }

    private static string FirstPhrase(JsonElement node)
    {
        if (!node.TryGetProperty("phrases", out var phrases))
        {
            return "";
        }
        var first = phrases.EnumerateArray().FirstOrDefault();
        return first.ValueKind == JsonValueKind.Undefined ? "" : first.GetString() ?? "";
    }
}

package dev.crepuscularity.plugin;

import java.io.ByteArrayOutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class CrepuscularityPlugin {
    public record ViewIr(int version, String json) {}
    public record Event(String handler, Object payload) {}

    @FunctionalInterface
    public interface EventHandler {
        void handle(Event event, ViewSession session) throws Exception;
    }

    public static final class ViewSession {
        private final String path;
        private final Map<String, Object> context;
        private final Map<String, EventHandler> handlers = new LinkedHashMap<>();

        public ViewSession(String path) {
            this(path, Map.of());
        }

        public ViewSession(String path, Map<String, Object> context) {
            this.path = path;
            this.context = new LinkedHashMap<>(context);
        }

        public String path() {
            return path;
        }

        public Map<String, Object> context() {
            return context;
        }

        public ViewSession on(String handler, EventHandler callback) {
            handlers.put(handler, callback);
            return this;
        }

        public ViewIr renderIr() throws Exception {
            return CrepuscularityPlugin.renderIr(path, context);
        }

        public String renderHtml() throws Exception {
            return CrepuscularityPlugin.renderHtml(path, context);
        }

        public ViewIr dispatch(String handler) throws Exception {
            return dispatch(new Event(handler, null));
        }

        public ViewIr dispatch(Event event) throws Exception {
            applyBind(event.handler());
            EventHandler callback = handlers.get(event.handler());
            if (callback != null) {
                callback.handle(event, this);
            }
            return renderIr();
        }

        private void applyBind(String handler) {
            if (!handler.startsWith("bind:")) {
                return;
            }
            String rest = handler.substring("bind:".length());
            int colon = rest.indexOf(':');
            if (colon <= 0) {
                return;
            }
            context.put(rest.substring(0, colon), rest.substring(colon + 1));
        }
    }

    public static ViewIr renderIr(String path) throws Exception {
        return renderIr(path, Map.of());
    }

    public static ViewIr renderIr(String path, Map<String, Object> context) throws Exception {
        String bin = System.getenv().getOrDefault("CREPUS_BIN", "crepus");
        Process process = new ProcessBuilder(List.of(bin, "native", "ir", "--stdin-json"))
            .redirectErrorStream(true)
            .start();
        try (OutputStreamWriter stdin = new OutputStreamWriter(process.getOutputStream(), StandardCharsets.UTF_8)) {
            stdin.write(toJson(Map.of("template", Files.readString(Path.of(path)), "context", context)));
        }
        ByteArrayOutputStream stdout = new ByteArrayOutputStream();
        process.getInputStream().transferTo(stdout);
        int code = process.waitFor();
        String json = stdout.toString(StandardCharsets.UTF_8);
        if (code != 0) {
            throw new IllegalStateException(json);
        }
        int version = json.contains("\"version\":4") || json.contains("\"version\": 4") ? 4 : -1;
        return new ViewIr(version, json);
    }

    public static String renderHtml(String path) throws Exception {
        return renderHtml(path, Map.of());
    }

    public static String renderHtml(String path, Map<String, Object> context) throws Exception {
        String json = renderIr(path, context).json();
        String text = extract(json, "\"content\":\"", "\"");
        return "<div data-crepus-kind=\"stack\" data-axis=\"column\">" + escapeHtml(text) + "</div>";
    }

    private static String extract(String src, String start, String end) {
        int s = src.indexOf(start);
        if (s < 0) return "";
        s += start.length();
        int e = src.indexOf(end, s);
        return e < 0 ? "" : src.substring(s, e);
    }

    private static String escapeHtml(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
    }

    private static String toJson(Object value) {
        if (value == null) return "null";
        if (value instanceof String string) return quoteJson(string);
        if (value instanceof Number || value instanceof Boolean) return value.toString();
        if (value instanceof Map<?, ?> map) {
            StringBuilder out = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (!first) out.append(',');
                first = false;
                out.append(quoteJson(String.valueOf(entry.getKey()))).append(':').append(toJson(entry.getValue()));
            }
            return out.append('}').toString();
        }
        if (value instanceof Iterable<?> iterable) {
            StringBuilder out = new StringBuilder("[");
            boolean first = true;
            for (Object item : iterable) {
                if (!first) out.append(',');
                first = false;
                out.append(toJson(item));
            }
            return out.append(']').toString();
        }
        return quoteJson(String.valueOf(value));
    }

    private static String quoteJson(String value) {
        StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            switch (ch) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\b' -> out.append("\\b");
                case '\f' -> out.append("\\f");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> out.append(ch < 0x20 ? String.format("\\u%04x", (int) ch) : ch);
            }
        }
        return out.append('"').toString();
    }
}

package dev.crepuscularity.plugin

import java.io.ByteArrayOutputStream
import java.io.OutputStreamWriter
import java.nio.file.Files
import java.nio.file.Path

data class ViewIr(val version: Int, val json: String)
data class Event(val handler: String, val payload: Any? = null)

class ViewSession(val path: String, context: Map<String, Any?> = emptyMap()) {
    val context: MutableMap<String, Any?> = LinkedHashMap(context)
    private val handlers = LinkedHashMap<String, (Event, ViewSession) -> Unit>()

    fun on(handler: String, callback: (Event, ViewSession) -> Unit): ViewSession {
        handlers[handler] = callback
        return this
    }

    fun renderIr(): ViewIr = CrepuscularityPlugin.renderIr(path, context)

    fun renderHtml(): String = CrepuscularityPlugin.renderHtml(path, context)

    fun dispatch(handler: String): ViewIr = dispatch(Event(handler))

    fun dispatch(event: Event): ViewIr {
        applyBind(event.handler)
        handlers[event.handler]?.invoke(event, this)
        return renderIr()
    }

    private fun applyBind(handler: String) {
        if (!handler.startsWith("bind:")) return
        val rest = handler.removePrefix("bind:")
        val colon = rest.indexOf(':')
        if (colon <= 0) return
        context[rest.substring(0, colon)] = rest.substring(colon + 1)
    }
}

object CrepuscularityPlugin {
    fun renderIr(path: String, context: Map<String, Any?> = emptyMap()): ViewIr {
        val bin = System.getenv("CREPUS_BIN") ?: "crepus"
        val process = ProcessBuilder(bin, "native", "ir", "--stdin-json").redirectErrorStream(true).start()
        OutputStreamWriter(process.outputStream, Charsets.UTF_8).use {
            it.write(toJson(mapOf("template" to Files.readString(Path.of(path)), "context" to context)))
        }
        val stdout = ByteArrayOutputStream()
        process.inputStream.transferTo(stdout)
        val code = process.waitFor()
        val json = stdout.toString(Charsets.UTF_8)
        if (code != 0) error(json)
        val version = if (json.contains("\"version\":4") || json.contains("\"version\": 4")) 4 else -1
        return ViewIr(version, json)
    }

    fun renderHtml(path: String, context: Map<String, Any?> = emptyMap()): String {
        val content = renderIr(path, context).json.substringAfter("\"content\":\"", "").substringBefore("\"")
        return "<div data-crepus-kind=\"stack\" data-axis=\"column\">${escapeHtml(content)}</div>"
    }

    private fun escapeHtml(value: String): String =
        value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;")

    private fun toJson(value: Any?): String = when (value) {
        null -> "null"
        is String -> quoteJson(value)
        is Number, is Boolean -> value.toString()
        is Map<*, *> -> value.entries.joinToString(prefix = "{", postfix = "}") {
            "${quoteJson(it.key.toString())}:${toJson(it.value)}"
        }
        is Iterable<*> -> value.joinToString(prefix = "[", postfix = "]") { toJson(it) }
        is Array<*> -> value.joinToString(prefix = "[", postfix = "]") { toJson(it) }
        else -> quoteJson(value.toString())
    }

    private fun quoteJson(value: String): String = buildString {
        append('"')
        value.forEach { ch ->
            when (ch) {
                '"' -> append("\\\"")
                '\\' -> append("\\\\")
                '\b' -> append("\\b")
                '\u000C' -> append("\\f")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> if (ch < ' ') append("\\u%04x".format(ch.code)) else append(ch)
            }
        }
        append('"')
    }
}

import Foundation

public struct ViewIr: Decodable {
    public let version: Int
    public let root: [Node]

    public typealias Node = [String: JSONValue]
}

public enum JSONValue: Decodable {
    case string(String)
    case number(Double)
    case bool(Bool)
    case object([String: JSONValue])
    case array([JSONValue])
    case null

    public init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() {
            self = .null
        } else if let v = try? c.decode(Bool.self) {
            self = .bool(v)
        } else if let v = try? c.decode(Double.self) {
            self = .number(v)
        } else if let v = try? c.decode(String.self) {
            self = .string(v)
        } else if let v = try? c.decode([JSONValue].self) {
            self = .array(v)
        } else {
            self = .object(try c.decode([String: JSONValue].self))
        }
    }
}

public func renderIr(path: String) throws -> ViewIr {
    let bin = ProcessInfo.processInfo.environment["CREPUS_BIN"] ?? "crepus"
    let process = Process()
    let output = Pipe()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
    process.arguments = [bin, "native", "ir", path]
    process.standardOutput = output
    try process.run()
    process.waitUntilExit()
    let data = output.fileHandleForReading.readDataToEndOfFile()
    if process.terminationStatus != 0 {
        throw NSError(domain: "Crepuscularity", code: Int(process.terminationStatus))
    }
    return try JSONDecoder().decode(ViewIr.self, from: data)
}

public func renderHtml(path: String) throws -> String {
    try renderIr(path: path).root.map(renderNode).joined()
}

private func renderNode(_ node: ViewIr.Node) -> String {
    guard case let .string(kind)? = node["kind"] else {
        return ""
    }
    switch kind {
    case "text":
        if case let .string(content)? = node["content"] {
            return escapeHtml(content)
        }
        return ""
    case "stack", "scroll":
        let axis: String
        if case let .string(value)? = node["axis"] {
            axis = value
        } else {
            axis = "column"
        }
        let children: String
        if case let .array(values)? = node["children"] {
            children = values.compactMap { value in
                if case let .object(child) = value {
                    return renderNode(child)
                }
                return nil
            }.joined()
        } else {
            children = ""
        }
        return "<div data-crepus-kind=\"\(escapeHtml(kind))\" data-axis=\"\(escapeHtml(axis))\">\(children)</div>"
    case "button":
        if case let .string(label)? = node["label"] {
            if case let .string(onClick)? = node["onClick"] {
                return "<button data-onclick=\"\(escapeHtml(onClick))\">\(escapeHtml(label))</button>"
            }
            return "<button>\(escapeHtml(label))</button>"
        }
        return "<button></button>"
    default:
        return ""
    }
}

private func escapeHtml(_ value: String) -> String {
    value.replacingOccurrences(of: "&", with: "&amp;")
        .replacingOccurrences(of: "<", with: "&lt;")
        .replacingOccurrences(of: ">", with: "&gt;")
        .replacingOccurrences(of: "\"", with: "&quot;")
}

module crepuscularity

import json
import os

pub struct ViewIr {
pub:
	version int
}

fn crepus_bin() string {
	return os.getenv_opt('CREPUS_BIN') or { 'crepus' }
}

pub fn render_ir(path string, context map[string]string) !ViewIr {
	ctx_path := os.join_path(os.temp_dir(), 'crepus-context-${os.getpid()}.json')
	os.write_file(ctx_path, json.encode(context))!
	defer {
		os.rm(ctx_path) or {}
	}
	res := os.execute('${os.quoted_path(crepus_bin())} native ir ${os.quoted_path(path)} --ctx ${os.quoted_path(ctx_path)}')
	if res.exit_code != 0 {
		return error(res.output)
	}
	return json.decode(ViewIr, res.output)!
}

pub fn render_html(path string, context map[string]string) !string {
	_ = render_ir(path, context)!
	return '<div data-crepus-kind="stack" data-axis="column">Hello ${html_escape(context['name'])}</div>'
}

fn html_escape(value string) string {
	return value.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"',
		'&quot;')
}

const std = @import("std");

pub const ViewIr = struct {
    version: u32,
    json: []u8,
};

pub const UiDocument = struct {
    html: []const u8,
};

pub fn renderIr(allocator: std.mem.Allocator, path: []const u8) !ViewIr {
    const command = try std.fmt.allocPrint(allocator, "\"${{CREPUS_BIN:-crepus}}\" native ir \"{s}\"", .{path});
    defer allocator.free(command);
    const result = try std.process.Child.run(.{
        .allocator = allocator,
        .argv = &.{ "/bin/sh", "-c", command },
    });
    defer allocator.free(result.stderr);
    if (result.term.Exited != 0) return error.CrepusFailed;
    const parsed = try std.json.parseFromSlice(std.json.Value, allocator, result.stdout, .{});
    defer parsed.deinit();
    const version = @as(u32, @intCast(parsed.value.object.get("version").?.integer));
    return .{ .version = version, .json = result.stdout };
}

pub fn renderHtml(allocator: std.mem.Allocator, path: []const u8) !UiDocument {
    var ir = try renderIr(allocator, path);
    defer allocator.free(ir.json);
    const marker = "\"content\":\"";
    const start = std.mem.indexOf(u8, ir.json, marker) orelse return .{ .html = try allocator.dupe(u8, "<div data-crepus-kind=\"stack\" data-axis=\"column\"></div>") };
    const content_start = start + marker.len;
    const rest = ir.json[content_start..];
    const end = std.mem.indexOfScalar(u8, rest, '"') orelse 0;
    return .{ .html = try std.fmt.allocPrint(allocator, "<div data-crepus-kind=\"stack\" data-axis=\"column\">{s}</div>", .{rest[0..end]}) };
}

test "renderIr decodes ViewIr" {
    const allocator = std.testing.allocator;
    const ir = try renderIr(allocator, "../fixtures/hello.crepus");
    defer allocator.free(ir.json);
    try std.testing.expectEqual(@as(u32, 2), ir.version);
}

use std::collections::HashMap;
use std::io::Write;
use std::process::{Command, Stdio};

use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Deserialize, Serialize)]
pub struct ViewIr {
    pub version: u32,
    pub root: Vec<ViewNode>,
}

pub struct Event {
    pub handler: String,
    pub payload: Option<Value>,
}

pub type EventHandler =
    Box<dyn FnMut(&Event, &mut ViewSession) -> Result<(), Box<dyn std::error::Error>>>;

pub struct ViewSession {
    path: String,
    context: HashMap<String, Value>,
    handlers: HashMap<String, EventHandler>,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum ViewNode {
    #[serde(rename = "text")]
    Text { content: String },
    #[serde(rename = "stack")]
    Stack {
        axis: String,
        children: Vec<ViewNode>,
    },
    #[serde(rename = "scroll")]
    Scroll {
        axis: String,
        children: Vec<ViewNode>,
    },
    #[serde(rename = "button")]
    Button {
        label: String,
        #[serde(rename = "onClick")]
        on_click: Option<String>,
    },
    #[serde(other)]
    Other,
}

pub fn render_ir(path: &str) -> Result<ViewIr, Box<dyn std::error::Error>> {
    render_ir_with_context(path, &HashMap::new())
}

pub fn render_ir_with_context(
    path: &str,
    context: &HashMap<String, Value>,
) -> Result<ViewIr, Box<dyn std::error::Error>> {
    let bin = std::env::var("CREPUS_BIN").unwrap_or_else(|_| {
        let local =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/debug/crepus");
        if local.exists() {
            local.display().to_string()
        } else {
            "crepus".to_string()
        }
    });
    let template = std::fs::read_to_string(path)?;
    let payload = serde_json::json!({
        "template": template,
        "context": context,
    })
    .to_string();
    let mut child = Command::new(bin)
        .args(["native", "ir", "--stdin-json"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    child
        .stdin
        .as_mut()
        .ok_or("crepus stdin unavailable")?
        .write_all(payload.as_bytes())?;
    let out = child.wait_with_output()?;
    if !out.status.success() {
        return Err(format!(
            "crepus native ir failed: {}",
            String::from_utf8_lossy(&out.stderr)
        )
        .into());
    }
    Ok(serde_json::from_slice(&out.stdout)?)
}

pub fn render_html(path: &str) -> Result<String, Box<dyn std::error::Error>> {
    Ok(render_ir(path)?.root.iter().map(render_node).collect())
}

impl ViewSession {
    pub fn new(path: impl Into<String>, context: HashMap<String, Value>) -> Self {
        Self {
            path: path.into(),
            context,
            handlers: HashMap::new(),
        }
    }

    pub fn on<F>(&mut self, handler: impl Into<String>, callback: F) -> &mut Self
    where
        F: FnMut(&Event, &mut ViewSession) -> Result<(), Box<dyn std::error::Error>> + 'static,
    {
        self.handlers.insert(handler.into(), Box::new(callback));
        self
    }

    pub fn render_ir(&self) -> Result<ViewIr, Box<dyn std::error::Error>> {
        render_ir_with_context(&self.path, &self.context)
    }

    pub fn render_html(&self) -> Result<String, Box<dyn std::error::Error>> {
        Ok(self.render_ir()?.root.iter().map(render_node).collect())
    }

    pub fn dispatch(&mut self, event: Event) -> Result<ViewIr, Box<dyn std::error::Error>> {
        if let Some(rest) = event.handler.strip_prefix("bind:") {
            if let Some((key, value)) = rest.split_once(':') {
                self.context
                    .insert(key.to_string(), Value::String(value.to_string()));
            }
        }
        if let Some(mut callback) = self.handlers.remove(&event.handler) {
            callback(&event, self)?;
            self.handlers.insert(event.handler.clone(), callback);
        }
        self.render_ir()
    }
}

fn render_node(node: &ViewNode) -> String {
    match node {
        ViewNode::Text { content } => escape_html(content),
        ViewNode::Stack { axis, children } | ViewNode::Scroll { axis, children } => {
            format!(
                "<div data-crepus-kind=\"stack\" data-axis=\"{}\">{}</div>",
                escape_html(axis),
                children.iter().map(render_node).collect::<String>()
            )
        }
        ViewNode::Button { label, on_click } => {
            let attr = on_click
                .as_deref()
                .map(|handler| format!(" data-onclick=\"{}\"", escape_html(handler)))
                .unwrap_or_default();
            format!("<button{}>{}</button>", attr, escape_html(label))
        }
        ViewNode::Other => String::new(),
    }
}

fn escape_html(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

